// Reuses gmail_normalizer.js logic inline
const item = $input.first().json;

function extractEmail(field) {
  if (!field) return '';
  if (typeof field === 'string') {
    const match = field.match(/<([^>\s]+@[^>\s]+)>/);
    return match ? match[1].trim() : field.trim();
  }
  if (field.value && Array.isArray(field.value) && field.value[0]?.address) return field.value[0].address;
  if (typeof field.text === 'string') {
    const match = field.text.match(/<([^>\s]+@[^>\s]+)>/);
    return match ? match[1].trim() : field.text.trim();
  }
  if (field.address) return String(field.address);
  return '';
}

function extractDisplayName(field) {
  if (!field) return '';
  if (typeof field === 'string') {
    const match = field.match(/^"?([^"<]+)"?\s*</);
    return match ? match[1].trim() : field.split('@')[0];
  }
  if (field.value && Array.isArray(field.value) && field.value[0]?.name) return field.value[0].name;
  if (typeof field.text === 'string') {
    const match = field.text.match(/^"?([^"<]+)"?\s*</);
    return match ? match[1].trim() : '';
  }
  return '';
}

function decodeBase64url(data) {
  if (!data) return '';
  const standard = data.replace(/-/g, '+').replace(/_/g, '/');
  return Buffer.from(standard, 'base64').toString('utf-8');
}

function searchParts(parts) {
  if (!Array.isArray(parts)) return '';
  for (const part of parts) {
    if (part.mimeType === 'text/plain' && part.body?.data) return decodeBase64url(part.body.data);
  }
  for (const part of parts) {
    if (Array.isArray(part.parts)) { const found = searchParts(part.parts); if (found) return found; }
  }
  for (const part of parts) {
    if (part.mimeType === 'text/html' && part.body?.data) {
      return decodeBase64url(part.body.data)
        .replace(/<style[\s\S]*?<\/style>/gi, '')
        .replace(/<[^>]+>/g, ' ')
        .replace(/&nbsp;/g, ' ')
        .replace(/\s{2,}/g, ' ').trim();
    }
  }
  return '';
}

function extractBody(item) {
  const payload = item.payload;
  if (!payload) return '';
  if (payload.body?.data) return decodeBase64url(payload.body.data);
  if (Array.isArray(payload.parts)) return searchParts(payload.parts);
  return '';
}

function headerValue(item, name) {
  const headers = item.payload?.headers;
  if (!Array.isArray(headers)) return '';
  const h = headers.find(h => h.name?.toLowerCase() === name.toLowerCase());
  return h?.value || '';
}

const fromRaw = item.From || item.from || headerValue(item, 'from');
const from    = extractEmail(fromRaw);
const subject = item.Subject || item.subject || headerValue(item, 'subject') || '';
const body    = extractBody(item);

return { json: { from, subject, body, messageId: item.id || '', threadId: item.threadId || '' } };

const body = $json.body || '';
const subject = $json.subject || '';

// ── Helpers ───────────────────────────────────────────────────────────────────
function grab(text, ...patterns) {
  for (const re of patterns) {
    const m = text.match(re);
    if (m && m[1]) return m[1].trim();
  }
  return '';
}

// ── Name ─────────────────────────────────────────────────────────────────────
const fullName = grab(body,
  /(?:Name|Contact|Buyer|Sender)[:\s]+([A-Z][a-zA-Z\-']+(?:\s[A-Z][a-zA-Z\-']+)+)/,
  /(?:From|Submitted by)[:\s]+([A-Z][a-zA-Z\-']+(?:\s[A-Z][a-zA-Z\-']+)+)/
);
const nameParts = fullName.split(/\s+/);
const firstName = nameParts[0] || 'Unknown';
const lastName  = nameParts.slice(1).join(' ') || 'Lead';

// ── Email ─────────────────────────────────────────────────────────────────────
const email = grab(body,
  /(?:Email|E-mail)[:\s]+([\w.+\-]+@[\w.\-]+\.[a-z]{2,})/i,
  /([\w.+\-]+@[\w.\-]+\.[a-z]{2,})/
).toLowerCase();

// ── Phone ─────────────────────────────────────────────────────────────────────
const phone = grab(body,
  /(?:Phone|Cell|Mobile|Tel)[:\s]+([\d\s().\-+]{7,20})/i,
  /\b((?:\+1[\s\-]?)?\(?\d{3}\)?[\s.\-]?\d{3}[\s.\-]?\d{4})\b/
).replace(/[^\d+]/g, '').replace(/^1/, '+1') || '';

// ── Property ─────────────────────────────────────────────────────────────────
const property = grab(body,
  /(?:Property|Address|Listing|Interested in|MLS)[:\s]+([^\n]{5,100})/i,
  /(?:about|for)[:\s]+([\d]+[^\n]{5,80}(?:St|Ave|Dr|Blvd|Rd|Ln|Way|Ct|Pl|TX)[^\n]{0,30})/i
);

// ── Message ───────────────────────────────────────────────────────────────────
const message = grab(body,
  /(?:Message|Comments?|Note|Question)[:\s]+([\s\S]{10,500}?)(?:\n{2,}|$)/i
);

// ── Source tag ───────────────────────────────────────────────────────────────
const source = $json.from.includes('matrix') ? 'Matrix MLS' : 'HAR.com';

return {
  json: {
    first_name: firstName,
    last_name: lastName,
    email,
    phone,
    lead_type: 'buyer',
    status: 'new',
    source,
    notes: [
      property ? `Property interest: ${property}` : '',
      message  ? `Message: ${message}` : '',
      `Email subject: ${subject}`,
      `Gmail message ID: ${$json.messageId}`,
    ].filter(Boolean).join('\n'),
  }
};

const existing = $input.first().json;
// API returns { count: N, leads: [...] }
const isDuplicate = (existing.count || 0) > 0;
return { json: { ...($('Parse Lead Data').first().json), isDuplicate } };
